export const pickText = (locale               = 'en') => TEXT[locale]                          ;

/**
 * Active product language, read fresh on every render pass from the document the Settings
 * preference resolves into. Never cached: switching language in Settings must re-project chrome
 * on the next render. Falls back to `en` when no document exists (Node / unit tests), so the
 * descriptor vocabulary pinned by tests resolves in English.
 */
export const activeLocale = ()               => {
  try {
    const lang = String((globalThis       )?.document?.documentElement?.lang || '').toLowerCase();
    return lang.startsWith('ar') ? 'ar' : 'en';
  } catch {
    return 'en';
  }
};

/** `{token}` interpolation — never concatenation, so Arabic word order survives. */
export const fill = (template        , values                                 )         =>
  String(template ?? '').replace(/\{(\w+)\}/g, (match, key) => (key in values ? String(values[key]) : match));

export default TEXT;
